// Purpose-separated original PG capture observation. No serialized identity,
// backup, cleanup token or caller flag constructs this live authority.
pub(crate) struct StoppedPgVerificationSource<'a> {
 serving:&'a RestoredPgServing,conn:&'a mut sqlx::AnyConnection,
 admin:&'a crate::auth::middleware::AdminUser,
 profile:EngineCatalogueProfile,tables:&'a BTreeMap<String,Table>,
 root_stamp:PhysicalStamp,files:&'a BTreeMap<String,(File,PhysicalStamp)>,dirs:&'a BTreeMap<String,(File,PhysicalStamp)>,
 native:Option<&'a crate::storage::restoration::admission::capture::NativeCaptureLeases>,
 preserved:Option<&'a OriginalRestoredAdmissionPreservation>,
 prior:Option<&'a super::PriorRestoredCaptureLeases>,
 completed:Option<&'a std::sync::Arc<crate::storage::attachment_upload::admission::committed_erasure::accounting::capture::NativeCompletedCapture>>,
 prior_completed:Option<&'a super::FinalizedCompletedCapture>,mixed:Option<&'a super::MixedCompletedCapture>,
 composite:Option<&'a crate::storage::attachment_upload::admission::committed_erasure::accounting::composite::CompositeOriginalSource>,
 certificate:Option<&'a crate::storage::restoration::admission::ClassifiedAdmissionSource>,
}
impl StoppedPgVerificationSource<'_> {
 pub(crate) fn path(&self)->&Path {&self.serving.proof.root.absolute}
 pub(crate) fn root_identity(&self)->io::Result<Identity>{identity(self.serving.proof.root.fd())}
 pub(crate) async fn current_human(&mut self)->anyhow::Result<String>{super::verification_source_human(self.conn,self.admin).await}
 fn physical(&self)->anyhow::Result<()> {
  let root=&self.serving.proof.root;self.serving.proof.physical_fence()?;
  ensure!(physical_stamp(root.fd())?==self.root_stamp,"Original observed PG root changed");
  for(path,(held,stamp))in self.files{ensure!(physical_stamp(held)?==*stamp&&physical_stamp(&root.leaf(path)?)?==*stamp,"Original observed PG file exchanged");}
  for(path,(held,stamp))in self.dirs{ensure!(physical_stamp(held)?==*stamp&&physical_stamp(&destination_directory(root.fd(),path)?)?==*stamp,"Original observed PG directory changed");}
  Ok(())
 }
 pub(crate) async fn fence(&mut self)->anyhow::Result<()> {
  self.physical()?;self.current_human().await?;self.serving.proof.verify_any_connection(self.conn).await?;
  if let Some(native)=self.native{native.recheck(self.conn).await?;}
  if let Some(preserved)=self.preserved{preserved.recheck(self.conn).await?;}
  if let Some(prior)=self.prior{prior.recheck_in(self.conn).await?;}
  if let Some(completed)=self.completed{completed.fence_in(self.conn).await?;}
  if let Some(prior)=self.prior_completed{prior.recheck_in(self.conn).await?;}
  if let Some(mixed)=self.mixed{mixed.recheck_in(self.conn).await?;}
  if let Some(composite)=self.composite{composite.recheck_in(self.conn).await?;}
  if let Some(certificate)=self.certificate{certificate.fence()?;}
  ensure!(pg_profile_any(self.conn).await?==self.profile,"Original observed PG profile changed");
  ensure!(pg_tables_any(self.conn,&shape_for_profile(self.profile)?).await?==*self.tables,"Original observed PG canonical snapshot changed");
  self.current_human().await?;self.serving.proof.verify_any_connection(self.conn).await?;self.physical()?;Ok(())
 }
}

